'use strict';
// Campaign saves remain compatible with the original milestone autosaves.
const PREVIOUS_SAVE=SAVE+'-previous';
let practiceMode=false;
function freshCampaign(character){return {character,story:0,coins:0,repairs:[],quests:[],crew:[],scraps:[]};}
function readCampaign(key){try{const value=JSON.parse(localStorage.getItem(key)||'null');if(!value||!['nova','sylvanas'].includes(value.character)||!Number.isInteger(value.story)||value.story<0||value.story>5)return null;return {...freshCampaign(value.character),...value};}catch{return null;}}
function writeCampaign(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{return false;}}
persist=function(){if(practiceMode)return;save.updatedAt=Date.now();writeCampaign(SAVE,save);};
function campaignSummary(value){return `${value.character==='nova'?'Nova':'Sylvanas'} · ${value.story>=5?'Tavern unlocked':chapters[value.story].name} · ${Number(value.coins)||0} coins`;}
function menuBack(){ $('#back').onclick=()=>title(); }
function characterChoices(){return `<div class="choices">${['nova','sylvanas'].map(name=>`<button class="choice ${selected===name?'selected':''}" data-character="${name}"><img src="assets/${name}.webp" alt="${name==='nova'?'Redheaded Nova':'Sylvanas'}"><strong>${name==='nova'?'Nova':'Sylvanas'}</strong><p>${name==='nova'?'Facility infiltration · cloak & rifle':'Haunted woodland · arrows & summons'}</p></button>`).join('')}</div>`;}
function wireCharacters(redraw){document.querySelectorAll('[data-character]').forEach(button=>button.onclick=()=>{selected=button.dataset.character;redraw();});}
title=function(){for(const k in keys)keys[k]=false;const current=readCampaign(SAVE);panel(`<p class="eyebrow">Bad decisions. Good company.</p><h1>Rum Island</h1><p>Two worlds. One portal. A spectacularly bad night.</p><div class="menu-actions"><button class="primary" id="new-game">New Game</button><button class="secondary" id="load-game" ${current?'':'disabled'}>Load Game</button><button class="secondary" id="test-levels">Test Early Levels</button><button class="secondary" id="sound">Sound ${soundOn?'ON':'OFF'}</button></div><p class="fine">${current?campaignSummary(current):'Your first bad decision awaits.'}${practiceMode?'<br>Practice session · campaign save protected':''}</p><p class="fine">A/D move · W/S ladders · S/C toggle crouch · Space jump<br>J attack · K ability · E interact · Esc pause<br>Landscape touch controls · Autosaves stay in this browser</p>`);$('#new-game').onclick=()=>newGameScreen();$('#load-game').onclick=()=>{if(current)loadGameScreen();};$('#test-levels').onclick=()=>testLevelScreen();$('#sound').onclick=()=>{soundOn=!soundOn;audioStart();ensureMusic(true);title();};};
function newGameScreen(){panel(`<p class="eyebrow">A fresh series of mistakes</p><h2>New Game</h2><p>Choose whose world the story begins in.</p>${characterChoices()}<button id="begin-new" class="primary">Begin the story</button><button id="back" class="secondary">Back</button><p class="fine">Your current autosave becomes the Previous Game backup.</p>`);wireCharacters(newGameScreen);menuBack();$('#begin-new').onclick=()=>{const current=readCampaign(SAVE);if(current&&!writeCampaign(PREVIOUS_SAVE,current)){saveError();return;}practiceMode=false;save=freshCampaign(selected);persist();audioStart();start(0);};}
function saveError(){panel('<h2>Save unavailable</h2><p>This browser could not store the campaign backup. Free some browser storage and try again, or use Test Early Levels.</p><button id="back" class="secondary">Back</button>');menuBack();}
function resumeCampaign(value){practiceMode=false;save=JSON.parse(JSON.stringify(value));selected=save.character;audioStart();save.story>=5?hub():start(save.story);}
function loadGameScreen(){const current=readCampaign(SAVE),previous=readCampaign(PREVIOUS_SAVE);panel(`<p class="eyebrow">Pick up the bad decisions</p><h2>Load Game</h2><div class="save-slots">${current?`<button id="load-current" class="choice"><strong>Autosave</strong><p>${campaignSummary(current)}</p></button>`:'<p>No autosave yet.</p>'}${previous?`<button id="load-previous" class="choice"><strong>Previous Game</strong><p>${campaignSummary(previous)}</p></button>`:''}</div><button id="back" class="secondary">Back</button><p class="fine">Loads the latest story milestone or your tavern. Active missions restart from their beginning.</p>`);menuBack();if(current)$('#load-current').onclick=()=>resumeCampaign(current);if(previous)$('#load-previous').onclick=()=>{if(current&&!writeCampaign(PREVIOUS_SAVE,current)){saveError();return;}if(!writeCampaign(SAVE,previous)){saveError();return;}resumeCampaign(previous);};}
function testLevelScreen(){const labels=['Solo intro','Ship tour & reunion','Bar fight','Steal the ship','Island arrival & card game'];panel(`<p class="eyebrow">Captain’s testing grounds</p><h2>Test Early Levels</h2>${characterChoices()}<div class="level-tests">${labels.map((label,i)=>`<button class="secondary" data-test-level="${i}">${i+1}. ${label}</button>`).join('')}</div><button id="back" class="secondary">Back</button><p class="fine">Practice mode keeps your campaign autosave and backup intact.<br>Esc → Main Menu → Load Game returns to your campaign.</p>`);wireCharacters(testLevelScreen);menuBack();document.querySelectorAll('[data-test-level]').forEach(button=>button.onclick=()=>{practiceMode=true;save=freshCampaign(selected);save.story=Number(button.dataset.testLevel);audioStart();start(save.story);});}
